const lessons=[{"sentences":[{"speaker":"A","text":"Welcome everyone to our annual college open day and thank you for joining us this morning.","position":1,"audioStartSeconds":0,"audioEndSeconds":5.391583333333333},{"speaker":"A","text":"Before you start exploring the campus, I need to share some important updates regarding our schedule.","position":2,"audioStartSeconds":5.591583333333333,"audioEndSeconds":11.597541666666666},{"speaker":"A","text":"Our main welcome talk was originally scheduled for the large auditorium near the southern entrance.","position":3,"audioStartSeconds":11.797541666666667,"audioEndSeconds":17.725375},{"speaker":"A","text":"However because of unexpected maintenance work, we have moved that session to the science building.","position":4,"audioStartSeconds":17.925375,"audioEndSeconds":23.814541666666667},{"speaker":"A","text":"You will find clear directional signs pointing towards the new location as soon as you step outside.","position":5,"audioStartSeconds":24.014541666666666,"audioEndSeconds":30.251666666666665},{"speaker":"A","text":"Regarding today's activities, you can join guided walking tours leaving every thirty minutes from the library.","position":6,"audioStartSeconds":30.451666666666668,"audioEndSeconds":37.114},{"speaker":"A","text":"If you prefer exploring independently, pick up a detailed campus map from the main reception desk.","position":7,"audioStartSeconds":37.314,"audioEndSeconds":43.770208333333336},{"speaker":"A","text":"Our department fair is hosted in the central courtyard where all academic advisors are waiting.","position":8,"audioStartSeconds":43.97020833333333,"audioEndSeconds":49.8465},{"speaker":"A","text":"You can ask questions about course requirements, tuition fees and student accommodation options directly.","position":9,"audioStartSeconds":50.0465,"audioEndSeconds":56.889291666666665},{"speaker":"A","text":"Please note that the cafeteria is closed for renovation today so lunch is served in the pavilion.","position":10,"audioStartSeconds":57.08929166666667,"audioEndSeconds":63.132333333333335},{"speaker":"A","text":"Free sandwiches and hot beverages will be provided for all registered visitors starting at noon.","position":11,"audioStartSeconds":63.33233333333333,"audioEndSeconds":69.53154166666667},{"speaker":"A","text":"If you lose any personal belongings during your visit, report the missing item to security.","position":12,"audioStartSeconds":69.73154166666667,"audioEndSeconds":75.6465},{"speaker":"A","text":"Our lost property office is conveniently located right beside the main entrance gates.","position":13,"audioStartSeconds":75.8465,"audioEndSeconds":81.45216666666667},{"speaker":"A","text":"Before you leave this afternoon, remember to complete our feedback form to win a prize.","position":14,"audioStartSeconds":81.65216666666667,"audioEndSeconds":86.94854166666667},{"speaker":"A","text":"Thank you again for coming and I hope you thoroughly enjoy discovering our vibrant college community.","position":15,"audioStartSeconds":87.14854166666667,"audioEndSeconds":92.99575}],"questions":[{"prompt":"Welcome talk new location: ______","answer":"science building","evidenceSentence":4,"evidence":"we have moved that session to the science building","explanation":"Người nói thông báo buổi nói chuyện chính đã được chuyển đến tòa nhà khoa học."},{"prompt":"Starting point for guided tours: ______","answer":"library","evidenceSentence":6,"evidence":"guided walking tours leaving every thirty minutes from the library","explanation":"Các tour tham quan có hướng dẫn khởi hành từ thư viện."},{"prompt":"Location of department fair: ______","answer":"central courtyard","evidenceSentence":8,"evidence":"Our department fair is hosted in the central courtyard","explanation":"Hội chợ khoa ngành được tổ chức ở sân trung tâm."},{"prompt":"Alternative lunch venue: ______","answer":"pavilion","evidenceSentence":10,"evidence":"lunch is served in the pavilion","explanation":"Bữa trưa được phục vụ tại nhà triển lãm (pavilion) do quán ăn tự phục vụ đóng cửa."},{"prompt":"Office for lost property: ______","answer":"security","evidenceSentence":12,"evidence":"report the missing item to security","explanation":"Đồ thất lạc cần được báo cáo cho bộ phận bảo vệ."},{"prompt":"Document to complete before leaving: ______","answer":"feedback form","evidenceSentence":14,"evidence":"remember to complete our feedback form","explanation":"Khách tham quan được nhắc nhở hoàn thành mẫu phản hồi trước khi ra về."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
